import sys, os, platform, subprocess, socket, threading
from pathlib import Path
root=Path(sys.argv[1]); sys.path.insert(0,str(root))
# Windows platform version discovery may invoke cmd /c ver; read before external-process guard.
platform.uname()
python_paths={Path(sys.executable).resolve(),Path(getattr(sys,"_base_executable",sys.executable)).resolve()}
python_paths.update(p.with_name("pythonw.exe") for p in tuple(python_paths) if p.with_name("pythonw.exe").is_file())
python_prefixes=tuple(subprocess.list2cmdline([str(p)])+" " for p in python_paths)
pair_state=threading.local()
original_socketpair=socket.socketpair
def isolated_socketpair(*args,**kwargs):
    pair_state.active=True
    try:return original_socketpair(*args,**kwargs)
    finally:pair_state.active=False
socket.socketpair=isolated_socketpair

def audit(event,args):
    if event == "socket.connect" and getattr(pair_state,"active",False):
        address=args[1]
        if isinstance(address,tuple) and address[0] in {"127.0.0.1","::1"} and address[1] != 5037:
            return
    if event in {"socket.connect","os.system","os.startfile","os.startfile/2"}:
        raise RuntimeError("AUDIT_BOUNDARY_BLOCKED:"+event)
    if event == "subprocess.Popen":
        executable=args[0]
        allowed=(executable is not None and Path(str(executable)).resolve() in python_paths)
        if executable is None and isinstance(args[1],str):
            allowed=args[1].startswith(python_prefixes)
        if not allowed:
            raise RuntimeError("AUDIT_BOUNDARY_BLOCKED:external_process")
sys.addaudithook(audit)
import pytest
raise SystemExit(pytest.main(sys.argv[2:]))
